require __DIR__.'/bootstrap.php';require_perm('expenses.manage');$me=user();$branch=is_admin()?null:require_branch();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(isset($_POST['set_status'])){$id=(int)$_POST['id'];$status=in_array($_POST['status'],['Paid','Pending','Overdue'],true)?$_POST['status']:'Paid';$pdo->prepare('UPDATE expenses SET status=? WHERE id=?'.($branch===null?'':' AND branch_id='.(int)$branch))->execute([$status,$id]);flash('success','Expense status updated.');redirect('expenses.php');}if(isset($_POST['delete'])){$id=(int)$_POST['id'];$pdo->beginTransaction();try{$pdo->prepare("DELETE FROM bank_transactions WHERE source_table='expenses' AND source_id=?")->execute([$id]);$pdo->prepare('DELETE FROM expenses WHERE id=?'.($branch===null?'':' AND branch_id='.(int)$branch))->execute([$id]);$pdo->commit();flash('success','Expense deleted.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Expense could not be deleted.');}}if(isset($_POST['update'])){$id=(int)$_POST['id'];$bankId=(int)($_POST['bank_account_id']??0);$old=$pdo->prepare('SELECT branch_id FROM expenses WHERE id=?'.($branch===null?'':' AND branch_id='.(int)$branch));$old->execute([$id]);$expenseBranch=(int)$old->fetchColumn();if(!$expenseBranch){flash('danger','Expense not found.');redirect('expenses.php');}if($bankId&&!bank_account_id_for_branch($bankId,$expenseBranch)){flash('danger','Select an active bank account for this branch.');redirect('expenses.php');}$oldBank=(int)$pdo->query('SELECT bank_account_id FROM expenses WHERE id='.(int)$id)->fetchColumn();$pdo->beginTransaction();try{$pdo->prepare('UPDATE expenses SET category=?,amount=?,expense_date=?,vendor=?,description=?,status=?,shipment_id=?,bank_account_id=? WHERE id=?')->execute([$_POST['category'],$_POST['amount'],$_POST['expense_date'],trim($_POST['vendor']),trim($_POST['description']),in_array($_POST['status']??'',['Paid','Pending','Overdue'],true)?$_POST['status']:'Paid',$_POST['shipment_id']?:null,$bankId?:null,$id]);if($bankId||$oldBank)sync_expense_bank_transaction($id,$bankId,(float)$_POST['amount'],$_POST['expense_date'].' '.date('H:i:s'));$pdo->commit();flash('success','Expense updated — bank statement kept in sync.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Expense could not be updated.');}redirect('expenses.php');}else{$expenseBranch=$branch??(int)$_POST['branch_id'];$bankId=(int)($_POST['bank_account_id']??0);if($bankId&&!bank_account_id_for_branch($bankId,$expenseBranch)){flash('danger','Select an active bank account for this branch.');redirect('expenses.php');}$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO expenses(category,amount,expense_date,vendor,description,status,shipment_id,branch_id,bank_account_id,recorded_by) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$_POST['category'],$_POST['amount'],$_POST['expense_date'],trim($_POST['vendor']),trim($_POST['description']),in_array($_POST['status']??'',['Paid','Pending','Overdue'],true)?$_POST['status']:'Paid',$_POST['shipment_id']?:null,$expenseBranch,$bankId?:null,$me['id']]);$expenseId=(int)$pdo->lastInsertId();if($bankId)add_bank_transaction($bankId,'Expense','expenses',$expenseId,(float)$_POST['amount'],$_POST['expense_date'].' '.date('H:i:s'));$pdo->commit();flash('success','Expense recorded.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Expense could not be recorded.');}}redirect('expenses.php');}
$filter=$branch===null?'':' WHERE e.branch_id='.(int)$branch;$rows=$pdo->query('SELECT e.*,s.awb,b.name bank_account_name FROM expenses e LEFT JOIN shipments s ON s.id=e.shipment_id LEFT JOIN bank_accounts b ON b.id=e.bank_account_id'.$filter.' ORDER BY e.expense_date DESC,e.id DESC')->fetchAll();$shipments=$pdo->query("SELECT id,awb FROM shipments WHERE status<>'Cancelled'".($branch===null?'':' AND branch_id='.(int)$branch).' ORDER BY shipment_date DESC')->fetchAll();$banks=$pdo->query('SELECT id,name,bank_name,account_number,branch_id FROM bank_accounts WHERE active=1'.($branch===null?'':' AND branch_id='.(int)$branch).' ORDER BY name')->fetchAll();$total=(float)$pdo->query("SELECT COALESCE(SUM(amount),0) FROM expenses".($branch===null?" WHERE expense_date>=DATE_FORMAT(CURDATE(),'%Y-%m-01')":" WHERE branch_id=".(int)$branch." AND expense_date>=DATE_FORMAT(CURDATE(),'%Y-%m-01')"))->fetchColumn();$title='Expenses';require __DIR__.'/partials/header.php';
